using System;
using System.Collections.Generic;
using System.Drawing;
using System.IO;
using System.Reflection;
using System.Threading;
using System.Threading.Tasks;
using System.Web.Script.Serialization;
using System.Windows.Forms;
using RockPro.CAD;

internal static class MaterialPlanUiChecks {
 const BindingFlags Flags=BindingFlags.Instance|BindingFlags.NonPublic;
 static T Field<T>(object form,string key){return (T)form.GetType().GetField(key,Flags).GetValue(form);}
 static object Invoke(object form,string method,params object[] args){return form.GetType().GetMethod(method,Flags).Invoke(form,args);}
 static void RunWork(object form,string method,params object[] args){SynchronizationContext.SetSynchronizationContext(null);Func<Task> work=()=>((Task)Invoke(form,method,args));var task=(Task)Invoke(form,"Run",work);var watch=System.Diagnostics.Stopwatch.StartNew();while(!task.IsCompleted){if(watch.ElapsedMilliseconds>30000)throw new TimeoutException("Material plan UI did not finish");Application.DoEvents();Thread.Sleep(5);}task.GetAwaiter().GetResult();Application.DoEvents();}
 static void Capture(Form form,string name){string folder=Environment.GetEnvironmentVariable("ROCKPRO_UI_EVIDENCE");if(String.IsNullOrEmpty(folder))return;Directory.CreateDirectory(folder);using(var bitmap=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(bitmap,new Rectangle(Point.Empty,form.Size));bitmap.Save(Path.Combine(folder,name+".png"));}}
 internal static void Run(){
  var json=new JavaScriptSerializer {MaxJsonLength=16000000};var fixture=Rpc.Obj(json.DeserializeObject(File.ReadAllText(Path.GetFullPath(Path.Combine(Application.StartupPath,"..","..","qa","fixtures","material-plan-ui.json")))));if(!Convert.ToBoolean(fixture["synthetic_test"])||Convert.ToBoolean(fixture["production_approved"]))throw new Exception("Material fixture scope invalid");
  string temp=Path.Combine(Path.GetTempPath(),"rockpro-material-ui-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(temp);bool oldCheck=Control.CheckForIllegalCrossThreadCalls,oldLanguage=UiText.IsEnglish;var context=SynchronizationContext.Current;Control.CheckForIllegalCrossThreadCalls=true;
  try{
   foreach(bool english in new[]{false,true})foreach(float scale in new[]{1f,1.5f}){
    UiText.SetLanguage(english,false);int calls=0,owner=Thread.CurrentThread.ManagedThreadId;
    using(var form=new MaterialPlanForm(delegate(string name,object args){calls++;if(Thread.CurrentThread.ManagedThreadId==owner)throw new Exception("Material backend called on UI thread");var a=Rpc.Obj(json.DeserializeObject(json.Serialize(args)));string key;if(name=="list_material_plans")key="listing";else if(name=="get_material_plan")key=Convert.ToString(a["plan_id"])=="plan-new"?"new":"old";else if(name=="compare_material_plans"){if(Convert.ToString(a["old_plan_id"])!="plan-old"||Convert.ToString(a["new_plan_id"])!="plan-new")throw new Exception("Wrong comparison direction");key="comparison";}else throw new Exception("Unexpected material write: "+name);return RevisionUi.Clone(Rpc.Obj(fixture[key]));},false)){
     form.Show();form.Scale(new SizeF(scale,scale));Application.DoEvents();RunWork(form,"LoadList",false);var catalog=Field<DataGridView>(form,"catalog");if(calls!=1||catalog.Rows.Count!=2||catalog.SelectedRows.Count!=0||Field<Button>(form,"export").Enabled||Field<Dictionary<string,object>>(form,"currentPlan")!=null)throw new Exception("Metadata listing auto-read/selected a plan");
     if(!Convert.ToString(catalog.Rows[0].Cells[3].Value).Contains(english?"Not checked":"Niesprawdzona"))throw new Exception("Metadata list faked freshness");
     Field<TextBox>(form,"planId").Text="plan-new";RunWork(form,"ReadPlan");if(calls!=2||Field<TextBox>(form,"oldPlanId").Text!="plan-old"||Field<Dictionary<string,object>>(form,"comparison")!=null||Convert.ToInt32(Field<DataGridView>(form,"groups").Rows[0].Cells[7].Value)!=3)throw new Exception("Plan read lost demand or auto-compared");
     RunWork(form,"Compare");var changes=Field<DataGridView>(form,"changes");if(calls!=3||changes.Rows.Count!=1||Convert.ToInt32(changes.Rows[0].Cells[4].Value)!=3||Convert.ToInt32(changes.Rows[0].Cells[5].Value)!=3||Convert.ToInt32(changes.Rows[0].Cells[6].Value)!=3||Convert.ToInt32(changes.Rows[0].Cells[7].Value)!=0)throw new Exception("Material shortage/reuse counts wrong");
     if(!Convert.ToString(changes.Rows[0].Cells[9].Value).Contains(english?"Not approved":"Niezaakceptowane")||Convert.ToString(Field<DataGridView>(form,"orders").Rows[0].Cells[3].Value)!="123.00")throw new Exception("Reuse was approved or commitment lost");
     if(!Field<Label>(form,"status").Text.Contains(english?"SYNTHETIC":"SYNTETYCZNY")||!Field<Label>(form,"status").Text.Contains(english?"Unallocated produced: 1":"Nieprzypisane wykonane: 1")||!Field<TextBox>(form,"sources").Text.Contains(english?"Incremental cost: —":"Koszt zmiany: —"))throw new Exception("Scope, produced remainder or unknown cost missing");
     foreach(string key in new[]{"catalog","groups","progress","changes","orders"})if(!Field<DataGridView>(form,key).ReadOnly)throw new Exception("Editable material table "+key);
     foreach(string key in new[]{"reload","next","read","compare","export"}){var button=Field<Button>(form,key);if(!button.Visible||!button.Parent.ClientRectangle.Contains(button.Bounds)||button.Width<button.GetPreferredSize(Size.Empty).Width)throw new Exception("Material action clipped: "+key+" "+english+" "+scale);}
     Capture(form,"material-"+(english?"en":"pl")+"-"+(scale>1?"150":"100"));if(!english&&scale==1){var tabs=Field<TabControl>(form,"tabs");foreach(int tab in new[]{0,1,4,5}){tabs.SelectedIndex=tab;Application.DoEvents();Capture(form,"material-tab-"+tab+"-pl-100");}}
     string output=Path.Combine(temp,"comparison-"+english+"-"+scale.ToString(System.Globalization.CultureInfo.InvariantCulture)+".json");Invoke(form,"ExportReport",output);var saved=Rpc.Obj(json.DeserializeObject(File.ReadAllText(output)));if(Convert.ToString(saved["kind"])!="material_plan_comparison_draft"||Convert.ToBoolean(saved["production_approved"])||!Rpc.Obj(saved["data"]).ContainsKey("old_progress_sha256"))throw new Exception("Comparison export lost evidence boundary");byte[] bytes=File.ReadAllBytes(output);try{Invoke(form,"ExportReport",output);throw new Exception("Existing material export overwritten");}catch(TargetInvocationException ex){if(!(ex.InnerException is IOException))throw;}if(Convert.ToBase64String(bytes)!=Convert.ToBase64String(File.ReadAllBytes(output)))throw new Exception("Existing export changed");
     UiText.SetLanguage(!english,false);if(calls!=3||Field<TextBox>(form,"planId").Text!="plan-new"||Field<TextBox>(form,"oldPlanId").Text!="plan-old"||!Field<Button>(form,"export").Enabled||!Convert.ToString(catalog.Rows[0].Cells[3].Value).Contains(!english?"Not checked":"Niesprawdzona"))throw new Exception("Language switch recalculated/lost data or left stale catalog language");
     Field<TextBox>(form,"oldPlanId").Text="different-old";if(Field<Dictionary<string,object>>(form,"comparison")!=null||changes.Rows.Count!=0||!Field<Button>(form,"export").Enabled||!Field<Button>(form,"export").Text.Contains(!english?"plan read":"odczyt"))throw new Exception("Old ID edit retained comparison or mislabeled plan export");Field<TextBox>(form,"planId").Text="plan-old";RunWork(form,"ReadPlan");if(Field<DataGridView>(form,"progress").Rows.Count!=2||!Field<Label>(form,"status").Text.Contains(!english?"Inputs changed in progress":"Wejście zmienione w trakcie"))throw new Exception("Recorded old progress/staleness lost");
     if(!english&&scale==1){Field<TabControl>(form,"tabs").SelectedIndex=2;Application.DoEvents();Capture(form,"material-progress-en-100");}form.Close();
    }
   }
   UiText.SetLanguage(false,false);foreach(string failure in new[]{"read","compare","scope"}){
    bool fail=false;using(var form=new MaterialPlanForm(delegate(string name,object args){if(fail&&name==(failure=="read"?"get_material_plan":"compare_material_plans")){if(failure!="scope")throw new Exception("SIMULATED_MATERIAL_READ_FAILURE");var bad=RevisionUi.Clone(Rpc.Obj(fixture["comparison"]));bad["orders_cancelled"]=true;return bad;}if(name=="get_material_plan")return RevisionUi.Clone(Rpc.Obj(fixture["new"]));if(name=="compare_material_plans")return RevisionUi.Clone(Rpc.Obj(fixture["comparison"]));throw new Exception("Unexpected tool");},false)){
     form.Show();Application.DoEvents();Field<TextBox>(form,"planId").Text="plan-new";RunWork(form,"ReadPlan");RunWork(form,"Compare");fail=true;RunWork(form,failure=="read"?"ReadPlan":"Compare");if(Field<Dictionary<string,object>>(form,"comparison")!=null||Field<DataGridView>(form,"changes").Rows.Count!=0||Field<Label>(form,"status").ForeColor!=Color.Firebrick)throw new Exception("Failed material read retained comparison");if(failure=="read"&&(Field<Button>(form,"export").Enabled||Field<Dictionary<string,object>>(form,"currentPlan")!=null))throw new Exception("Failed read retained old plan");if(failure!="read"&&!Field<Button>(form,"export").Enabled)throw new Exception("Failed comparison discarded separately timestamped plan read");form.Close();
    }
   }
   int pages=0;using(var form=new MaterialPlanForm(delegate(string name,object args){if(name!="list_material_plans")throw new Exception("Paging performed non-list operation");var a=Rpc.Obj(json.DeserializeObject(json.Serialize(args)));var reply=RevisionUi.Clone(Rpc.Obj(fixture["listing"]));var rows=Rpc.Rows(reply["plans"]);if(pages++==0){if(a.ContainsKey("after_plan_id"))throw new Exception("Initial cursor invented");reply["plans"]=new object[]{rows[0]};reply["has_more"]=true;reply["next_cursor"]="plan-new";}else{if(Convert.ToString(a["after_plan_id"])!="plan-new")throw new Exception("Cursor changed");reply["plans"]=new object[]{rows[1]};}return reply;},false)){
    form.Show();Application.DoEvents();RunWork(form,"LoadList",false);if(!Field<Button>(form,"next").Enabled)throw new Exception("Next page not available");RunWork(form,"LoadList",true);if(pages!=2||Field<Button>(form,"next").Enabled||Convert.ToString(Field<DataGridView>(form,"catalog").Rows[0].Cells[0].Value)!="plan-old")throw new Exception("Paging boundary wrong");form.Close();
   }
   using(var form=new MaterialPlanForm(delegate(string name,object args){if(name!="list_material_plans")throw new Exception("Empty list performed write");return new Dictionary<string,object>{{"plans",new object[0]},{"next_cursor",null},{"has_more",false},{"production_approved",false}};},false)){
    form.Show();Application.DoEvents();RunWork(form,"LoadList",false);if(Field<DataGridView>(form,"catalog").Rows.Count!=0||Field<Button>(form,"export").Enabled||Field<Button>(form,"next").Enabled)throw new Exception("Empty list invented data");form.Close();
   }
   Console.WriteLine("PASS: material plan UI PL/EN 100/150, metadata vs verified read, 4 produced/3 candidate/1 remainder, preserved expense, unknown delta, explicit comparison, failure invalidation, paging and non-overwriting readonly export");
  }finally{SynchronizationContext.SetSynchronizationContext(context);Control.CheckForIllegalCrossThreadCalls=oldCheck;UiText.SetLanguage(oldLanguage,false);string resolved=Path.GetFullPath(temp),root=Path.GetFullPath(Path.GetTempPath()).TrimEnd(Path.DirectorySeparatorChar)+Path.DirectorySeparatorChar;if(!resolved.StartsWith(root,StringComparison.OrdinalIgnoreCase)||!Path.GetFileName(resolved).StartsWith("rockpro-material-ui-",StringComparison.Ordinal))throw new Exception("Refusing cleanup outside material UI temp directory");Directory.Delete(resolved,true);}
 }
}
